package com.ruoyi.paicli.service;

import com.ruoyi.paicli.domain.*;
import java.util.*;

/** 内部只读预览回执和最终恢复参数同域、同attempt绑定，不用模型或本机排序授予恢复权限。 */
public final class PcSnapshotPermit {
    public static final String PREVIEW="snapshot__preview";
    public static final Set<String> FIELDS=Set.of("snapshotMetadataId","snapshotId","snapshotVersion","previewToolCallId","currentFingerprint","restorePreview");
    private final PcStore store;private final PcArtifactService artifacts;
    public PcSnapshotPermit(PcStore store){this(store,null);}
    public PcSnapshotPermit(PcStore store,PcArtifactService artifacts){this.store=store;this.artifacts=artifacts;}
    public Map<String,Object> select(PcRecord task,Map<String,Object> arguments){long offset=arguments.containsKey("offset")?PcJson.number(arguments,"offset"):1;offset=Math.max(1,offset);if(offset>10000)throw PcException.invalid("恢复offset超过正式快照查询范围");List<PcRecord> snapshots=store.mapper.list(PcTable.SNAPSHOT,task.getWorkspaceId(),task.getOwnerId(),null,"READY").stream().filter(r->Objects.equals(r.getSessionId(),task.getSessionId())&&Objects.equals(r.getRunnerId(),task.getRunnerId())&&"PRE_TURN".equals(store.data(r).get("phase"))).sorted(Comparator.comparingLong(PcRecord::getSequenceNumber).thenComparingLong(PcRecord::getId).reversed()).toList();if(offset>snapshots.size())throw PcException.conflict("当前会话没有该offset的正式PRE_TURN快照");return target(task,snapshots.get((int)offset-1));}
    public Map<String,Object> target(PcRecord task,PcRecord snapshot){if(!snapshot.getState().equals("READY")||!Objects.equals(snapshot.getWorkspaceId(),task.getWorkspaceId())||!Objects.equals(snapshot.getOwnerId(),task.getOwnerId())||!Objects.equals(snapshot.getSessionId(),task.getSessionId())||!Objects.equals(snapshot.getRunnerId(),task.getRunnerId())||!"PRE_TURN".equals(store.data(snapshot).get("phase")))throw PcException.deny("恢复目标必须是当前会话和Runner的正式PRE_TURN快照");Map<String,Object> data=store.data(snapshot);String commit=PcJson.text(data,"commitId");if(commit.isBlank())commit=PcJson.text(data,"snapshotId");if(!commit.matches("[a-f0-9]{40,64}"))throw PcException.conflict("快照没有真实commitId");return Map.of("snapshotMetadataId",String.valueOf(snapshot.getId()),"snapshotId",commit,"commitId",commit,"snapshotVersion",snapshot.getVersion());}
    public Map<String,Object> validateTarget(PcRecord task,Map<String,Object> arguments){PcRecord snapshot=store.require(PcTable.SNAPSHOT,PcJson.number(arguments,"snapshotMetadataId"),true);Map<String,Object> target=target(task,snapshot);for(String field:List.of("snapshotMetadataId","snapshotId","snapshotVersion"))if(!Objects.toString(arguments.get(field),"").equals(Objects.toString(target.get(field),"")))throw PcException.conflict("恢复目标版本或commit已变化");return target;}
    public Map<String,Object> parsePreview(PcRecord task,Map<String,Object> arguments,Map<String,Object> result,String callId){Map<String,Object> target=validateTarget(task,arguments);String text=PcJson.text(result,"text");if(text.isBlank()||text.getBytes(java.nio.charset.StandardCharsets.UTF_8).length>16L*1024*1024)throw PcException.invalid("内部预览回执须保留不超过16MiB的完整JSON proof正文");Map<String,Object> body;try{body=store.json.read(text);}catch(RuntimeException invalid){throw PcException.invalid("内部预览回执正文不是JSON proof");}String commit=PcJson.text(body,"commitId");if(commit.isBlank())commit=PcJson.text(body,"snapshotId");if(!commit.equals(target.get("snapshotId")))throw PcException.conflict("预览回执commit不是冻结目标");for(String field:List.of("snapshotMetadataId","snapshotVersion"))if(!Objects.toString(body.get(field),"").equals(Objects.toString(target.get(field),"")))throw PcException.conflict("预览回执metadata或版本不是冻结目标");Map<String,Object> proof=body.get("restorePreview") instanceof Map<?,?>?PcJson.object(body,"restorePreview"):body.get("preview") instanceof Map<?,?>?PcJson.object(body,"preview"):body;PcRunnerService.validatePreview(proof,commit);if(!Objects.equals(body.get("currentFingerprint"),proof.get("currentFingerprint")))throw PcException.conflict("预览回执顶层与proof指纹不同");if(body.containsKey("previewArtifactId")){if(artifacts==null)throw PcException.invalid("预览产物服务不可用");proof=new PcSnapshotArtifact(store,artifacts).proof(task,callId,body);}return proof;}
    public Map<String,Object> validateRestore(PcRecord task,Map<String,Object> arguments){Map<String,Object> target=validateTarget(task,arguments),selected=select(task,arguments);if(!target.equals(selected))throw PcException.conflict("恢复offset与正式目标不同");String id=PcJson.text(arguments,"previewToolCallId");if(!id.matches("[A-Za-z0-9._:-]{1,128}"))throw PcException.invalid("恢复缺少内部预览调用ID");String key="task:"+task.getId()+":call:"+id;PcRecord call=store.mapper.findKey(PcTable.TOOL_CALL,key,true),receipt=store.mapper.findKey(PcTable.TOOL_RECEIPT,key,true);if(call==null||receipt==null||!PREVIEW.equals(call.getKind())||!call.getState().equals("COMPLETED")||!receipt.getState().equals("COMPLETED")||!Objects.equals(receipt.getSessionId(),task.getSessionId())||!Objects.equals(receipt.getOwnerId(),task.getOwnerId()))throw PcException.deny("恢复必须引用当前任务已完成的正式预览回执");Map<String,Object> cp=store.data(call);PcRecord lease=store.mapper.findKey(PcTable.TASK_LEASE,"task:"+task.getId(),true);if(PcJson.number(cp,"leaseId")!=lease.getId()||PcJson.number(cp,"fencingToken")!=task.getFencingToken())throw PcException.deny("旧attempt预览不能授予当前恢复");Map<String,Object> sourceArguments=PcJson.object(cp,"arguments");for(String field:List.of("snapshotMetadataId","snapshotId","snapshotVersion"))if(!Objects.toString(arguments.get(field),"").equals(Objects.toString(sourceArguments.get(field),"")))throw PcException.conflict("恢复目标不同于正式预览许可");Map<String,Object> proof=parsePreview(task,sourceArguments,PcJson.object(store.data(receipt),"result"),id);Map<String,Object> rd=store.data(receipt);if(!Objects.equals(rd.get("beforeHash"),proof.get("currentFingerprint"))||!Objects.equals(rd.get("afterHash"),proof.get("currentFingerprint")))throw PcException.conflict("只读预览回执前后资源哈希与当前proof不同");if(!Boolean.TRUE.equals(proof.get("canRestore"))||!store.json.hash(proof).equals(store.json.hash(PcJson.object(arguments,"restorePreview")))||!Objects.equals(proof.get("currentFingerprint"),arguments.get("currentFingerprint")))throw PcException.conflict("恢复参数或当前指纹与正式预览回执不同");Map<String,Object> context=new LinkedHashMap<>(target);context.put("currentFingerprint",proof.get("currentFingerprint"));context.put("restorePreview",proof);context.put("previewToolCallId",id);context.put("previewReceiptId",String.valueOf(receipt.getId()));Map<String,Object> body=store.json.read(PcJson.text(PcJson.object(rd,"result"),"text"));if(body.containsKey("previewArtifactId"))context.put("previewArtifact",Map.of("artifactId",String.valueOf(PcJson.number(body,"previewArtifactId")),"sha256",body.get("previewArtifactSha256"),"size",body.get("previewArtifactSize")));return context;}
}
